"use client";

import React, { useState, useEffect } from "react";
import useSWR from "swr";
import { useUserContext } from "../../components/providers/UserProvider";
import { useRouter } from "next/navigation";
import {
  Calendar, Clock, MapPin, QrCode, ScanLine, X, Loader2,
  CheckCircle2, ArrowRight, User, AlertTriangle, ChevronRight
} from "lucide-react";
import QRCode from "react-qr-code";
import { toast } from "../../lib/toast";

const fetcher = (url) => fetch(url).then((res) => res.json());

function MeetingCountdownTimer({ booking }) {
  const [timeLeft, setTimeLeft] = useState('');
  const [isLive, setIsLive] = useState(false);

  useEffect(() => {
    const calculateTime = () => {
      let targetDate = null;
      if (booking.date) {
        const dateStr = booking.date === 'Today' 
          ? new Date().toISOString().split('T')[0] 
          : booking.date;
        const timeStr = booking.time || '18:00';
        targetDate = new Date(`${dateStr}T${timeStr}:00`);
      }

      if (!targetDate || isNaN(targetDate.getTime())) {
        const created = booking.created_at ? new Date(booking.created_at) : new Date();
        targetDate = new Date(created.getTime() + 2 * 60 * 60 * 1000);
      }

      const diff = targetDate.getTime() - Date.now();
      if (diff <= 0 && diff > -3600000) {
        setIsLive(true);
        setTimeLeft('≡ƒƒó Happening Now');
      } else if (diff <= -3600000) {
        setTimeLeft('');
      } else {
        const hrs = Math.floor(diff / (1000 * 60 * 60));
        const mins = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
        const secs = Math.floor((diff % (1000 * 60)) / 1000);
        setTimeLeft(`ΓÅ│ Starts in ${hrs > 0 ? `${hrs}h ` : ''}${mins}m ${secs}s`);
      }
    };

    calculateTime();
    const interval = setInterval(calculateTime, 1000);
    return () => clearInterval(interval);
  }, [booking]);

  if (!timeLeft) return null;

  return (
    <div className={`mt-2 flex items-center gap-1.5 px-3 py-1 rounded-xl text-[11px] font-extrabold border ${
      isLive ? 'bg-emerald-50 text-emerald-700 border-emerald-200 animate-pulse' : 'bg-purple-50 text-purple-700 border-purple-100'
    }`}>
      <span>{timeLeft}</span>
    </div>
  );
}

export default function BookingsPage() {
  const router = useRouter();
  const { user } = useUserContext();
  const [activeTab, setActiveTab] = useState("Active"); // "Active" | "History"

  // Modals state
  const [showQrModal, setShowQrModal] = useState(false);
  const [showScanModal, setShowScanModal] = useState(false);
  const [showDisputeModal, setShowDisputeModal] = useState(false);
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [selectedBooking, setSelectedBooking] = useState(null);
  const [bookingToCancel, setBookingToCancel] = useState(null);

  // Verification state
  const [scanStatus, setScanStatus] = useState("idle"); // idle, processing, success, error
  const [scanMessage, setScanMessage] = useState("");
  const [manualCode, setManualCode] = useState("");

  // Dispute state
  const [disputeLoading, setDisputeLoading] = useState(false);
  const [disputeSuccess, setDisputeSuccess] = useState(false);
  const [cancelLoading, setCancelLoading] = useState(null); // bookingId being cancelled

  const { data, error, mutate, isLoading } = useSWR(user ? "/api/bookings" : null, fetcher);
  const { data: walletData } = useSWR(user ? "/api/wallet" : null, fetcher);
  const sparksBalance = walletData?.wallet
    ? (walletData.wallet.purchased || 0) + (walletData.wallet.bonus || 0) + (walletData.wallet.creator || 0)
    : null;
  const bookings = data?.bookings || [];

  const activeBookings = bookings.filter(b => b.status === "Requested" || b.status === "Accepted" || b.status === "Confirmed");
  const pastBookings = bookings.filter(b => ["Completed", "Rejected", "Cancelled", "Meeting Completed", "Booking Closed", "AutoRefunded", "Disputed", "Canceled"].includes(b.status));

  const displayList = activeTab === "Active" ? activeBookings : pastBookings;

  useEffect(() => {
    if (!user && typeof window !== "undefined") {
      router.push("/login");
    }
  }, [user, router]);

  if (!user) return null;

  // Has the meeting time passed? (for showing Report Issue button)
  // - If scheduledAt exists: check if it's passed
  // - Fallback: show button 2h after booking was created (covers weekday-name bookings)
  const now = Date.now();
  const isMeetingTimePassed = (booking) => {
    if (booking.scheduledAt) {
      return now > new Date(booking.scheduledAt).getTime();
    }
    // Fallback for bookings without a parseable scheduledAt
    const created = booking.created_at ? new Date(booking.created_at) : null;
    if (!created || isNaN(created.getTime())) return false;
    return now > created.getTime() + 2 * 60 * 60 * 1000; // 2 hours after creation
  };

  // Handle Manual Code Verification
  const handleVerifyCode = async () => {
    if (scanStatus === "processing" || scanStatus === "success" || !selectedBooking) return;

    if (manualCode.trim() === selectedBooking.meetingCode) {
      setScanStatus("processing");
      try {
        const res = await fetch("/api/bookings", {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ bookingId: selectedBooking.id, action: "complete", meetingCode: manualCode.trim() })
        });

        const data = await res.json();
        if (data.ok || data.success) {
          setScanStatus("success");
          setScanMessage("Verification successful! Sparks have been credited.");
          setTimeout(() => {
            setShowScanModal(false);
            setScanStatus("idle");
            setManualCode("");
            setSelectedBooking(null);
            mutate();
          }, 2000);
        } else {
          setScanStatus("error");
          setScanMessage(data.error || "Verification failed");
          setTimeout(() => setScanStatus("idle"), 2500);
        }
      } catch (e) {
        setScanStatus("error");
        setScanMessage("Network error during verification.");
        setTimeout(() => setScanStatus("idle"), 2500);
      }
    } else {
      setScanStatus("error");
      setScanMessage("Invalid Code for this meeting.");
      setTimeout(() => setScanStatus("idle"), 2500);
    }
  };

  // Handle Cancel Request (guest cancels before host accepts)
  const initiateCancel = (booking) => {
    setBookingToCancel(booking);
    setShowCancelModal(true);
  };

  const handleCancel = async () => {
    if (!bookingToCancel || cancelLoading) return;
    setCancelLoading(bookingToCancel.id);
    try {
      const res = await fetch("/api/bookings", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ bookingId: bookingToCancel.id, action: "cancel" })
      });
      const d = await res.json();
      if (d.success) {
        toast.success('Booking cancelled. Sparks refunded! ΓÜí');
        mutate();
        setShowCancelModal(false);
        setBookingToCancel(null);
      } else {
        toast.error(d.error || 'Failed to cancel. Please try again.');
      }
    } catch {
      toast.error('Network error. Please try again.');
    } finally {
      setCancelLoading(null);
    }
  };

  const handleDispute = async () => {
    if (!selectedBooking || disputeLoading) return;
    setDisputeLoading(true);
    try {
      const res = await fetch("/api/bookings", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ bookingId: selectedBooking.id, action: "dispute" })
      });
      const data = await res.json();
      if (data.success) {
        setDisputeSuccess(true);
        setTimeout(() => {
          setShowDisputeModal(false);
          setDisputeSuccess(false);
          setSelectedBooking(null);
          mutate();
        }, 2200);
      } else {
        alert(data.error || "Failed to report issue. Please try again.");
      }
    } catch (e) {
      alert("Network error. Please try again.");
    } finally {
      setDisputeLoading(false);
    }
  };

  const statusColor = (status) => {
    if (status === "Completed" || status === "Meeting Completed") return "text-emerald-600 bg-emerald-50 border-emerald-100";
    if (status === "Rejected" || status === "Cancelled" || status === "Canceled") return "text-rose-600 bg-rose-50 border-rose-100";
    if (status === "AutoRefunded") return "text-amber-600 bg-amber-50 border-amber-100";
    if (status === "Disputed") return "text-orange-600 bg-orange-50 border-orange-100";
    if (status === "Booking Closed") return "text-zinc-500 bg-zinc-50 border-zinc-200";
    return "text-purple-600 bg-purple-50 border-purple-100";
  };

  const statusLabel = (status) => {
    if (status === "AutoRefunded") return "Auto Refunded";
    if (status === "Meeting Completed") return "Completed";
    if (status === "Booking Closed") return "Closed";
    return status;
  };

  return (
    <div className="min-h-screen bg-[#fafafa] pb-24 anim-fade-in">
      {/* Header */}
      <header className="sticky top-0 z-40 bg-white/80 backdrop-blur-xl border-b border-zinc-100 px-4 py-4 shadow-sm flex items-center justify-between">
        <div>
          <h1 className="text-xl font-black text-zinc-900 tracking-tight flex items-center gap-2">
            <Calendar size={20} className="text-[#7c3aed]" />
            My Meetings
          </h1>
        </div>
        {/* Sparks balance ΓÇö helps user know how many Sparks they have before booking */}
        {sparksBalance !== null && (
          <div className="flex items-center gap-1 px-3 py-1.5 rounded-full text-[11px] font-black" style={{ background: '#f3f0ff', color: '#7c3aed' }}>
            <span>ΓÜí</span>
            <span>{sparksBalance.toLocaleString()}</span>
          </div>
        )}
      </header>

      {/* Tabs */}
      <div className="px-4 mt-4">
        <div className="flex bg-zinc-100/80 p-1 rounded-xl">
          {["Active", "History"].map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 py-2 text-[13px] font-bold rounded-lg transition-all duration-200 ${
                activeTab === tab
                  ? "bg-white text-zinc-900 shadow-sm"
                  : "text-zinc-500 hover:text-zinc-700"
              }`}
            >
              {tab}
              {tab === "Active" && activeBookings.length > 0 && (
                <span className="ml-1.5 inline-flex items-center justify-center w-4 h-4 bg-[#7c3aed] text-white text-[9px] font-black rounded-full">
                  {activeBookings.length}
                </span>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* List */}
      <div className="px-4 mt-6 space-y-4">
        {isLoading && (
          <div className="flex flex-col items-center justify-center py-20 text-zinc-400">
            <Loader2 className="animate-spin mb-2" size={24} />
            <p className="text-xs font-bold">Loading meetings...</p>
          </div>
        )}

        {!isLoading && displayList.length === 0 && (
          <div className="flex flex-col items-center text-center justify-center py-16 px-6 bg-white rounded-2xl border border-dashed border-zinc-200">
            <div className="w-12 h-12 bg-purple-50 rounded-full flex items-center justify-center text-purple-600 mb-3">
              <Calendar size={20} strokeWidth={2.5} />
            </div>
            <h3 className="text-sm font-black text-zinc-900 mb-1">No {activeTab.toLowerCase()} meetings</h3>
            <p className="text-xs text-zinc-500 font-medium">
              {activeTab === "Active" 
                ? "You don't have any upcoming experiences right now." 
                : "You haven't completed any meetings yet."}
            </p>
            {activeTab === "Active" && (
              <button 
                onClick={() => router.push("/")}
                className="mt-5 bg-zinc-900 text-white text-xs font-bold px-5 py-2.5 rounded-full hover:scale-105 active:scale-95 transition-all"
              >
                Browse Experiences
              </button>
            )}
          </div>
        )}

        {displayList.map(booking => {
          const isGuest = booking.guestId === user.uid;
          const otherPerson = isGuest ? booking.hostName : booking.guestName;
          const roleLabel = isGuest ? "You are joining" : "You are hosting";
          const canReport = isGuest && isMeetingTimePassed(booking) && 
            ["Requested", "Confirmed", "Accepted"].includes(booking.status);

          return (
            <div key={booking.id} className="bg-white rounded-2xl p-4 border border-zinc-100 shadow-[0_4px_20px_rgba(0,0,0,0.03)] transition-all hover:shadow-[0_8px_30px_rgba(124,58,237,0.08)]">
              {/* Card Header */}
              <div className="flex justify-between items-start mb-3">
                <div>
                  <span className={`inline-block px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-wider border ${statusColor(booking.status)} mb-2`}>
                    {statusLabel(booking.status)}
                  </span>
                  <h3 className="text-[15px] font-black text-zinc-900 leading-tight">
                    {booking.title}
                  </h3>
                  <p className="text-[11px] text-zinc-500 font-bold flex items-center gap-1.5 mt-1">
                    <User size={12} /> {roleLabel} <span className="text-zinc-800">{otherPerson}</span>
                  </p>
                </div>
                <div className="text-right">
                  <span className="text-xs font-black text-[#7c3aed] flex items-center gap-1 justify-end">
                    ΓÜí {booking.price}
                  </span>
                </div>
              </div>

              {/* Card Details */}
              <div className="flex flex-wrap gap-y-2 gap-x-4 mt-4 bg-zinc-50 rounded-xl p-3 border border-zinc-100/50">
                <div className="flex items-center gap-1.5 text-[11px] font-semibold text-zinc-600">
                  <Calendar size={13} className="text-zinc-400" />
                  {booking.date || "Any Day"}
                </div>
                <div className="flex items-center gap-1.5 text-[11px] font-semibold text-zinc-600">
                  <Clock size={13} className="text-zinc-400" />
                  {booking.time || "Flexible"}
                </div>
                <div className="flex items-center gap-1.5 text-[11px] font-semibold text-zinc-600 w-full truncate">
                  <MapPin size={13} className="text-zinc-400 flex-shrink-0" />
                  <span className="truncate">{booking.location || "Campus"}</span>
                </div>
              </div>

              {/* Countdown Timer for Active Bookings */}
              {activeTab === "Active" && (
                <MeetingCountdownTimer booking={booking} />
              )}

              {/* Auto-refund info banner */}
              {booking.status === "AutoRefunded" && (
                <div className="mt-3 flex items-center gap-2 bg-amber-50 border border-amber-100 rounded-xl px-3 py-2">
                  <AlertTriangle size={14} className="text-amber-500 flex-shrink-0" />
                  <p className="text-[10px] font-bold text-amber-700">
                    Meeting time passed without QR scan ΓÇö {booking.price} Sparks auto-refunded.
                  </p>
                </div>
              )}

              {/* Disputed info banner */}
              {booking.status === "Disputed" && (
                <div className="mt-3 flex items-center gap-2 bg-orange-50 border border-orange-100 rounded-xl px-3 py-2">
                  <AlertTriangle size={14} className="text-orange-500 flex-shrink-0" />
                  <p className="text-[10px] font-bold text-orange-700">
                    Issue reported ΓÇö Sparks held in escrow pending review.
                  </p>
                </div>
              )}

              {/* Action Buttons (Only for Active tab) */}
              {activeTab === "Active" && (
                <div className="mt-4 flex gap-2">
                  {isGuest ? (
                    <>
                      {/* Cancel button: only for Requested (before host accepts), with instant refund */}
                      {booking.status === "Requested" && (
                        <button
                          onClick={() => initiateCancel(booking)}
                          disabled={cancelLoading === booking.id}
                          className="w-12 h-[46px] bg-zinc-50 text-zinc-500 border border-zinc-200 rounded-xl flex items-center justify-center hover:bg-rose-50 hover:text-rose-500 hover:border-rose-100 active:scale-[0.98] transition-all disabled:opacity-50"
                          title="Cancel Request (full refund)"
                        >
                          {cancelLoading === booking.id
                            ? <Loader2 size={16} className="animate-spin" />
                            : <X size={16} strokeWidth={2.5} />}
                        </button>
                      )}
                      <button 
                        onClick={() => { setSelectedBooking(booking); setShowQrModal(true); }}
                        className="flex-1 bg-zinc-900 text-white rounded-xl py-3 text-xs font-black flex items-center justify-center gap-2 hover:bg-zinc-800 active:scale-[0.98] transition-all"
                      >
                        <QrCode size={16} /> View Ticket
                      </button>
                      {canReport && (
                        <button
                          onClick={() => { setSelectedBooking(booking); setShowDisputeModal(true); }}
                          className="w-12 h-[46px] bg-rose-50 text-rose-500 border border-rose-100 rounded-xl flex items-center justify-center hover:bg-rose-100 active:scale-[0.98] transition-all"
                          title="Report Issue"
                        >
                          <AlertTriangle size={16} strokeWidth={2.5} />
                        </button>
                      )}
                    </>
                  ) : (
                    <button 
                      onClick={() => { setSelectedBooking(booking); setShowScanModal(true); setScanStatus("idle"); }}
                      className="flex-1 bg-[#7c3aed] text-white rounded-xl py-3 text-xs font-black flex items-center justify-center gap-2 hover:bg-[#6d28d9] active:scale-[0.98] transition-all shadow-[0_4px_15px_rgba(124,58,237,0.3)]"
                    >
                      <ScanLine size={16} /> Scan Guest QR
                    </button>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* ΓöÇΓöÇΓöÇ MODAL: GUEST QR TICKET ΓöÇΓöÇΓöÇ */}
      {showQrModal && selectedBooking && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm anim-fade-in">
          <div className="bg-white rounded-3xl w-full max-w-[340px] overflow-hidden shadow-2xl anim-scale-in flex flex-col">
            <div className="p-4 border-b flex items-center justify-between bg-zinc-50">
              <h3 className="text-sm font-black text-zinc-900">Meeting Ticket</h3>
              <button onClick={() => setShowQrModal(false)} className="w-8 h-8 rounded-full bg-white border flex items-center justify-center text-zinc-500 hover:text-black">
                <X size={16} strokeWidth={2.5} />
              </button>
            </div>

            <div className="p-8 flex flex-col items-center text-center">
              <p className="text-xs font-bold text-zinc-500 mb-6 max-w-[200px]">
                Show this QR code to <strong className="text-zinc-900">{selectedBooking.hostName}</strong> when you meet.
              </p>

              <div className="bg-white p-4 rounded-3xl shadow-[0_0_40px_rgba(124,58,237,0.15)] border-2 border-purple-100">
                <QRCode value={selectedBooking.meetingCode} size={180} fgColor="#000" />
              </div>

              <div className="mt-8 bg-zinc-50 px-4 py-2 rounded-xl border border-dashed border-zinc-300 w-full">
                <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest mb-1">Manual Code</p>
                <p className="text-xl font-black tracking-[0.3em] text-zinc-900">{selectedBooking.meetingCode}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ΓöÇΓöÇΓöÇ MODAL: CANCEL REQUEST ΓöÇΓöÇΓöÇ */}
      {showCancelModal && bookingToCancel && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm anim-fade-in">
          <div className="bg-white rounded-3xl w-full max-w-[340px] p-6 shadow-2xl anim-scale-in text-center border border-zinc-100">
            <div className="w-12 h-12 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-4">
              <AlertTriangle size={24} />
            </div>
            <h3 className="text-lg font-black text-zinc-900 mb-2">Cancel Booking?</h3>
            <p className="text-xs text-zinc-500 font-medium mb-6 leading-relaxed">
              Are you sure you want to cancel this booking request? Your <strong className="text-zinc-800">{bookingToCancel.price} Sparks</strong> will be refunded immediately.
            </p>
            <div className="flex gap-2">
              <button
                onClick={() => {
                  setShowCancelModal(false);
                  setBookingToCancel(null);
                }}
                disabled={cancelLoading === bookingToCancel.id}
                className="flex-1 py-3 rounded-xl border border-zinc-200 text-xs font-bold text-zinc-600 hover:bg-zinc-50 transition-all disabled:opacity-50"
              >
                Keep it
              </button>
              <button
                onClick={handleCancel}
                disabled={cancelLoading === bookingToCancel.id}
                className="flex-1 bg-rose-500 text-white py-3 rounded-xl text-xs font-black hover:bg-rose-600 active:scale-95 transition-all shadow-md flex items-center justify-center gap-1 disabled:opacity-50"
              >
                {cancelLoading === bookingToCancel.id ? (
                  <Loader2 size={16} className="animate-spin" />
                ) : (
                  <>Yes, Cancel</>
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ΓöÇΓöÇΓöÇ MODAL: HOST VERIFICATION ΓöÇΓöÇΓöÇ */}
      {showScanModal && selectedBooking && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md anim-fade-in">
          <div className="absolute top-4 right-4 z-50">
             <button onClick={() => { setShowScanModal(false); setManualCode(""); }} className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center text-white hover:bg-white/20">
               <X size={20} strokeWidth={2.5} />
             </button>
          </div>

          <div className="w-full max-w-[340px] flex flex-col items-center">
            <h3 className="text-white text-lg font-black mb-2">Verify Meeting</h3>
            <p className="text-white/60 text-xs font-medium mb-6 text-center">
              Enter the 6-digit code from {selectedBooking.guestName}&apos;s phone to receive your Sparks.
            </p>

            <div className="w-full bg-zinc-900/50 p-6 rounded-3xl border border-white/10 relative">
              {scanStatus === "success" ? (
                <div className="absolute inset-0 bg-emerald-500 rounded-3xl flex flex-col items-center justify-center text-white anim-fade-in z-10">
                  <CheckCircle2 size={48} className="mb-2" />
                  <p className="font-black text-base">Verified!</p>
                </div>
              ) : scanStatus === "processing" ? (
                <div className="absolute inset-0 bg-black/80 rounded-3xl flex flex-col items-center justify-center text-white anim-fade-in z-10 backdrop-blur-sm">
                  <Loader2 size={32} className="animate-spin mb-3 text-[#7c3aed]" />
                  <p className="font-bold text-xs">Verifying...</p>
                </div>
              ) : (
                <div className="flex flex-col gap-4">
                  <input
                    type="text"
                    maxLength={6}
                    value={manualCode}
                    onChange={(e) => setManualCode(e.target.value.toUpperCase())}
                    placeholder="Enter 6-digit code"
                    className="w-full bg-black/50 border border-white/20 rounded-xl px-4 py-4 text-center text-2xl font-black text-white tracking-[0.3em] uppercase outline-none focus:border-[#7c3aed] transition-colors"
                  />
                  <button
                    onClick={handleVerifyCode}
                    disabled={manualCode.length !== 6}
                    className="w-full bg-[#7c3aed] disabled:bg-zinc-800 disabled:text-zinc-500 hover:bg-[#6d28d9] text-white py-3.5 rounded-xl text-xs font-black uppercase tracking-wider transition-all"
                  >
                    Verify & Claim Sparks
                  </button>
                </div>
              )}
            </div>

            {scanStatus === "error" && (
              <div className="mt-6 bg-rose-500/20 text-rose-200 px-4 py-2 rounded-xl text-xs font-bold border border-rose-500/50 anim-fade-up">
                {scanMessage}
              </div>
            )}
          </div>
        </div>
      )}

      {/* ΓöÇΓöÇΓöÇ MODAL: REPORT ISSUE ΓöÇΓöÇΓöÇ */}
      {showDisputeModal && selectedBooking && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-4 bg-black/50 backdrop-blur-sm anim-fade-in">
          <div className="bg-white rounded-3xl w-full max-w-[380px] overflow-hidden shadow-2xl anim-scale-in">
            <div className="p-5 border-b border-zinc-100 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-full bg-rose-50 flex items-center justify-center">
                  <AlertTriangle size={16} className="text-rose-500" />
                </div>
                <h3 className="text-sm font-black text-zinc-900">Report Issue</h3>
              </div>
              <button 
                onClick={() => { setShowDisputeModal(false); setDisputeSuccess(false); }}
                className="w-8 h-8 rounded-full bg-zinc-100 flex items-center justify-center text-zinc-500 hover:bg-zinc-200"
              >
                <X size={16} strokeWidth={2.5} />
              </button>
            </div>

            {disputeSuccess ? (
              <div className="p-8 flex flex-col items-center text-center">
                <div className="w-16 h-16 rounded-full bg-emerald-50 flex items-center justify-center mb-4">
                  <CheckCircle2 size={32} className="text-emerald-500" />
                </div>
                <h4 className="text-base font-black text-zinc-900 mb-2">Issue Reported!</h4>
                <p className="text-xs text-zinc-500 font-medium">
                  Your Sparks are held safely. Auto-refund will process within 1 hour if the meeting didn&apos;t happen.
                </p>
              </div>
            ) : (
              <div className="p-5">
                <div className="bg-rose-50 border border-rose-100 rounded-2xl p-4 mb-5">
                  <p className="text-xs font-bold text-rose-700 leading-relaxed">
                    Did <strong>{selectedBooking.hostName}</strong> not show up for &quot;{selectedBooking.title}&quot;?
                  </p>
                  <p className="text-[11px] text-rose-500 mt-1.5">
                    If the QR code was never scanned, your {selectedBooking.price} Sparks will be auto-refunded within 1 hour.
                  </p>
                </div>

                <div className="bg-amber-50 border border-amber-100 rounded-xl px-3 py-2.5 mb-5 flex items-start gap-2">
                  <AlertTriangle size={13} className="text-amber-500 mt-0.5 flex-shrink-0" />
                  <p className="text-[10px] text-amber-700 font-semibold leading-relaxed">
                    Only report if the meeting genuinely didn't happen. False reports may affect your account standing.
                  </p>
                </div>

                <div className="flex gap-2">
                  <button 
                    onClick={() => setShowDisputeModal(false)}
                    className="flex-1 py-3 rounded-xl border border-zinc-200 text-xs font-black text-zinc-600 hover:bg-zinc-50 transition-all"
                  >
                    Cancel
                  </button>
                  <button 
                    onClick={handleDispute}
                    disabled={disputeLoading}
                    className="flex-1 py-3 rounded-xl bg-rose-500 text-white text-xs font-black flex items-center justify-center gap-2 hover:bg-rose-600 active:scale-[0.98] transition-all disabled:opacity-60"
                  >
                    {disputeLoading ? <Loader2 size={14} className="animate-spin" /> : <AlertTriangle size={14} />}
                    {disputeLoading ? "Reporting..." : "Report Issue"}
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Camera, X, ArrowLeft, Loader2, Sparkles, Image as ImageIcon, CheckCircle } from 'lucide-react';
import imageCompression from 'browser-image-compression';
import { toast } from '../../../lib/toast';

export default function CreatePhotoClient({ currentUser }) {
  const router = useRouter();

  const [caption, setCaption] = useState('');
  const [category, setCategory] = useState('Food & Meets');
  const [file, setFile] = useState(null);
  const [filePreview, setFilePreview] = useState('');
  const [uploading, setUploading] = useState(false);

  const handleFileChange = (e) => {
    const selected = e.target.files[0];
    if (selected) {
      setFile(selected);
      setFilePreview(URL.createObjectURL(selected));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!currentUser) {
      toast.error('Please log in to post a photo.');
      router.push('/login');
      return;
    }

    if (!file) {
      toast.error('Please select a photo to share!');
      return;
    }

    setUploading(true);
    try {
      // 1. Compress image before upload
      const options = { maxSizeMB: 0.3, maxWidthOrHeight: 1200, useWebWorker: true };
      const compressedFile = await imageCompression(file, options);

      // 2. Upload to Cloudinary using unsigned preset
      const cloudName = process.env.NEXT_PUBLIC_CLOUDINARY_CLOUD_NAME || 'dqq68y5ep';
      const uploadPreset = process.env.NEXT_PUBLIC_CLOUDINARY_UPLOAD_PRESET || 'meetify_unsigned';

      const formData = new FormData();
      formData.append('file', compressedFile);
      formData.append('upload_preset', uploadPreset);

      const cloudRes = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
        method: 'POST',
        body: formData,
      });

      if (!cloudRes.ok) throw new Error('Cloudinary upload failed');
      const cloudData = await cloudRes.json();
      const photoUrl = cloudData.secure_url;

      // 3. Post to backend
      const res = await fetch('/api/posts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          photoUrl,
          caption,
          category,
          location: 'Campus',
        }),
      });

      if (res.ok) {
        toast.success('Campus Moment posted successfully! ≡ƒÄë');
        router.push('/');
      } else {
        const d = await res.json();
        toast.error(d.error || 'Failed to save post.');
      }
    } catch (err) {
      console.error(err);
      toast.error('Failed to upload photo. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="min-h-screen bg-zinc-50/50 px-4 py-6 max-w-[540px] mx-auto anim-fade-in pb-20">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <button
          onClick={() => router.back()}
          className="flex items-center gap-1.5 text-xs font-black text-zinc-600 hover:text-zinc-950 transition-colors"
        >
          <ArrowLeft size={16} />
          <span>Back</span>
        </button>
        <span className="text-[10px] font-black text-pink-600 uppercase tracking-widest bg-pink-50 border border-pink-100 px-3 py-1 rounded-full">
          Campus Moments
        </span>
      </div>

      <div className="bg-white rounded-3xl p-6 border border-zinc-200/80 shadow-xs space-y-5">
        <div>
          <h1 className="text-xl font-black text-zinc-950 tracking-tight flex items-center gap-2">
            <Camera size={22} className="text-pink-500" />
            Share Campus Photo
          </h1>
          <p className="text-xs text-zinc-500 font-semibold mt-1">
            Post food photos, coffee meets, or campus vibes with your peers.
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Photo Picker Container */}
          <div>
            <label className="text-[10px] font-black uppercase tracking-wider text-zinc-400 block mb-1.5">
              Select Photo
            </label>
            {filePreview ? (
              <div className="relative h-60 w-full rounded-2xl overflow-hidden bg-zinc-100 border border-zinc-200 group">
                <img src={filePreview} alt="Preview" className="w-full h-full object-cover" />
                <button
                  type="button"
                  onClick={() => { setFile(null); setFilePreview(''); }}
                  className="absolute top-3 right-3 p-1.5 rounded-full bg-black/60 text-white hover:bg-black transition-colors"
                >
                  <X size={16} />
                </button>
              </div>
            ) : (
              <label className="flex flex-col items-center justify-center h-52 w-full rounded-2xl border-2 border-dashed border-zinc-300 bg-zinc-50 hover:bg-pink-50/50 hover:border-pink-300 transition-all cursor-pointer text-center p-4">
                <div className="w-12 h-12 rounded-full bg-pink-100 text-pink-600 flex items-center justify-center mb-2">
                  <ImageIcon size={22} />
                </div>
                <span className="text-xs font-black text-zinc-800">Click to choose a photo</span>
                <span className="text-[10px] text-zinc-400 font-medium mt-1">PNG, JPG, WEBP up to 10MB</span>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFileChange}
                  className="hidden"
                />
              </label>
            )}
          </div>

          {/* Category Pills Grid */}
          <div>
            <label className="text-[10px] font-black uppercase tracking-wider text-zinc-400 block mb-2">
              Select Category
            </label>
            <div className="grid grid-cols-2 gap-2.5">
              {[
                { id: 'Food & Meets', label: 'Food & Meets', emoji: '≡ƒìò' },
                { id: 'Campus Vibe', label: 'Campus Vibe', emoji: '≡ƒÅ½' },
                { id: 'Study Spot', label: 'Study Spot', emoji: '≡ƒôÜ' },
                { id: 'Event / Hangout', label: 'Event / Hangout', emoji: '≡ƒÄë' },
              ].map((cat) => {
                const isSelected = category === cat.id;
                return (
                  <button
                    key={cat.id}
                    type="button"
                    onClick={() => setCategory(cat.id)}
                    className={`flex items-center gap-2.5 p-3 rounded-2xl border text-xs font-extrabold transition-all cursor-pointer ${
                      isSelected
                        ? 'bg-gradient-to-r from-pink-500 to-purple-600 text-white border-transparent shadow-md scale-[1.02]'
                        : 'bg-zinc-50 border-zinc-200/90 text-zinc-700 hover:bg-zinc-100'
                    }`}
                  >
                    <span className="text-base">{cat.emoji}</span>
                    <span className="truncate">{cat.label}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Caption */}
          <div>
            <label className="text-[10px] font-black uppercase tracking-wider text-zinc-400 block mb-1.5">
              Caption
            </label>
            <textarea
              value={caption}
              onChange={(e) => setCaption(e.target.value)}
              placeholder="e.g. Trying the new cold coffee at Canteen #2! Great spot for quick connects Γÿò"
              className="w-full p-3.5 rounded-2xl border border-zinc-200 bg-zinc-50 text-xs font-medium text-zinc-900 placeholder-zinc-400 focus:bg-white focus:outline-none focus:border-pink-500 transition-all min-h-[90px]"
            />
          </div>

          {/* Submit button */}
          <button
            type="submit"
            disabled={uploading || !file}
            className="w-full py-4 rounded-2xl text-xs font-black text-white bg-gradient-to-r from-pink-500 to-purple-600 hover:opacity-95 disabled:opacity-50 transition-all flex items-center justify-center gap-2 shadow-md cursor-pointer uppercase tracking-wider"
          >
            {uploading ? (
              <>
                <Loader2 size={16} className="animate-spin" />
                <span>Uploading to Cloudinary...</span>
              </>
            ) : (
              <>
                <Sparkles size={16} />
                <span>Post Campus Moment</span>
              </>
            )}
          </button>
        </form>
      </div>
    </div>
  );
}

