function EarningsChart({ balance }) {
  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const values = [20, 50, 10, 80, 40, balance > 100 ? 100 : balance, balance];
  const max = Math.max(...values, 100);

  return (
    <div className="bg-[var(--bg-elevated)] border border-[var(--border-subtle)] rounded-3xl p-5 mb-5 shadow-sm">
      <div className="flex justify-between items-end mb-4">
        <div>
          <span className="text-[10px] font-black uppercase tracking-widest text-[var(--text-muted)]">Weekly Earnings</span>
          <p className="text-xl font-black text-[var(--text-primary)] mt-1">
            +{values.reduce((a,b)=>a+b,0)} <span className="text-[10px] text-[var(--text-secondary)]">Sparks</span>
          </p>
        </div>
        <div className="px-2 py-1 bg-emerald-500/10 text-emerald-600 text-[9px] font-black rounded-lg">
          +12.5%
        </div>
      </div>

      <div className="flex items-end justify-between h-32 gap-2 mt-6">
        {values.map((val, i) => (
          <div key={i} className="flex-1 flex flex-col items-center gap-2 group cursor-pointer h-full justify-end">
            <div className="w-full relative flex items-end justify-center rounded-lg overflow-hidden bg-[var(--bg-surface)] h-full">
              <div 
                className="w-full bg-gradient-to-t from-[#7c3aed] to-[#a78bfa] rounded-t-lg transition-all duration-700 ease-out group-hover:opacity-80"
                style={{ height: `${(val / max) * 100}%` }}
              />
            </div>
            <span className="text-[9px] font-bold text-[var(--text-muted)] uppercase">{days[i]}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function formatDate(iso) {
  if (!iso) return '';
  try {
    const d = new Date(iso);
    return d.toLocaleDateString('en-IN', { month: 'short', day: 'numeric', year: 'numeric' }) +
      ' ┬╖ ' + d.toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit' });
  } catch { return iso; }
}

export default function WalletPage() {
  const router = useRouter();
  const [wallet, setWallet] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedPack, setSelectedPack] = useState(PACKS[1]);
  const [requestLoading, setRequestLoading] = useState(false);
  const [toast, setToast] = useState('');
  const [pendingRequests, setPendingRequests] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [intentId, setIntentId] = useState(null);
  const [exactAmountInr, setExactAmountInr] = useState(0);
  const [intentLoading, setIntentLoading] = useState(false);

  const balance = wallet
    ? (wallet.purchased || 0) + (wallet.bonus || 0) + (wallet.creator || 0)
    : 0;

  const loadWallet = useCallback(async () => {
    try {
      const res = await fetch('/api/wallet');
      if (!res.ok) return;
      const data = await res.json();
      if (data.wallet) setWallet(data.wallet);
      if (data.transactions) setTransactions(data.transactions);
      if (data.pendingRequests) setPendingRequests(data.pendingRequests);
    } catch (err) {
      console.error('[WalletPage] load error:', err);
    } finally {
      await new Promise(r => setTimeout(r, 300));
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    loadWallet();
    const onUpdate = () => loadWallet();
    window.addEventListener('wallet-updated', onUpdate);
    return () => window.removeEventListener('wallet-updated', onUpdate);
  }, [loadWallet]);

  const openPaymentModal = async (pack = selectedPack) => {
    if (pendingRequests.length >= 3) {
      setToast('ΓÜá∩╕Å You have reached the limit of 3 pending payment requests. Please wait for verification.');
      return;
    }
    setSelectedPack(pack);
    setIntentLoading(true);

    try {
      const res = await fetch('/api/wallet/intent', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sparks: pack.sparks,
          amount_inr: pack.inr > 1 ? pack.inr - 1 : pack.inr,
          pack_name: `${pack.sparks} Sparks`,
          pack_key: pack.key
        }),
      });
      const data = await res.json();
      if (res.ok) {
        setIntentId(data.intentId);
        setExactAmountInr(data.amount_inr);
        setIsModalOpen(true);
      } else {
        setToast(data.error || 'Failed to generate payment intent');
      }
    } catch (err) {
      setToast('Network error');
    } finally {
      setIntentLoading(false);
    }
  };

  const closeModal = async () => {
    setIsModalOpen(false);
  };

  const downloadQRCode = async () => {
    try {
      const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=500x500&data=${encodeURIComponent(`upi://pay?pa=chirag2006chak@oksbi&pn=Meetifyy&am=${exactAmountInr}&cu=INR`)}`;
      const response = await fetch(qrUrl);
      const blob = await response.blob();
      const blobUrl = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = blobUrl;
      link.download = `meetify-payment-Γé╣${exactAmountInr}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(blobUrl);
    } catch (err) {
      const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=500x500&data=${encodeURIComponent(`upi://pay?pa=chirag2006chak@oksbi&pn=Meetifyy&am=${exactAmountInr}&cu=INR`)}`;
      window.open(qrUrl, '_blank');
