            className="text-[10px] font-bold text-purple-600 hover:text-purple-700 flex items-center gap-1 cursor-pointer"
          >
            Clear Filter <X className="w-3 h-3" />
          </button>
        )}
      </div>

      {/* Interest Circles Row */}
      <div className="flex gap-4 overflow-x-auto no-scrollbar pb-2">
        {interests.map(interest => {
          const meta = INTEREST_META[interest] || { Icon: Star, color: '#7c3aed' };
          const { Icon } = meta;
          const isSelected = selectedInterest === interest;

          return (
            <button
              key={interest}
              type="button"
              onClick={() => handleInterestClick(interest)}
              className={`flex flex-col items-center flex-shrink-0 cursor-pointer group transition-all outline-none focus:outline-none ${
                isSelected ? 'scale-105' : 'hover:scale-105'
              }`}
            >
              <div 
                className={`w-14 h-14 rounded-full transition-all ${
                  isSelected 
                    ? 'p-[2.5px] bg-gradient-to-tr from-purple-600 via-purple-500 to-indigo-600 shadow-md shadow-purple-500/25' 
                    : 'p-[2px] border-2 border-zinc-200 group-hover:border-purple-300'
                }`}
              >
                <div 
                  className={`w-full h-full rounded-full flex items-center justify-center transition-colors ${
                    isSelected ? 'bg-purple-50' : 'bg-zinc-50'
                  }`}
                  style={{ color: meta.color }}
                >
                  <Icon className="w-6 h-6" />
                </div>
              </div>
              <span className={`text-[10px] font-bold max-w-[70px] truncate text-center mt-1 transition-colors ${
                isSelected ? 'text-purple-700 font-extrabold' : 'text-zinc-600'
              }`}>
                {interest}
              </span>
            </button>
          );
        })}
      </div>

      {/* Suggested Students Drawer / Section */}
      {selectedInterest && (
        <div className="mt-4 p-4 rounded-3xl bg-purple-50/60 border border-purple-100/80 anim-fade-in">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-purple-600" />
              <h3 className="text-xs font-black text-zinc-900 tracking-tight">
                Students into <span className="text-purple-600">{selectedInterest}</span>
              </h3>
              <span className="text-[10px] font-black px-2 py-0.5 rounded-full bg-purple-100 text-purple-700">
                {matchingUsers.length}
              </span>
            </div>

            <Link 
              href={`/discover?interest=${encodeURIComponent(selectedInterest)}`}
              className="text-[10px] font-bold text-purple-600 hover:underline flex items-center gap-0.5"
            >
              Explore All <ChevronRight className="w-3 h-3" />
            </Link>
          </div>

          {matchingUsers.length === 0 ? (
            <div className="text-center py-6 bg-white/80 rounded-2xl border border-purple-100">
              <p className="text-xs font-semibold text-zinc-500">
                No other students tagged with <span className="font-bold text-purple-600">{selectedInterest}</span> yet.
              </p>
            </div>
          ) : (
            <div className="flex gap-3 overflow-x-auto no-scrollbar pb-1">
              {matchingUsers.map(student => (
                <div
                  key={student.id}
                  onClick={() => router.push(`/users/${student.id}`)}
                  className="w-[150px] flex-shrink-0 bg-white rounded-2xl p-3 border border-purple-100/80 flex flex-col items-center text-center cursor-pointer hover:border-purple-300 hover:shadow-md transition-all group"
                >
                  <div className="w-12 h-12 rounded-full overflow-hidden mb-2 relative border-2 border-purple-200 group-hover:scale-105 transition-transform">
                    <img 
                      src={getAvatar(student)} 
                      alt={student.full_name || 'Student'} 
                      className="w-full h-full object-cover" 
                    />
                  </div>
                  <span className="text-xs font-black text-zinc-900 truncate max-w-full group-hover:text-purple-600 transition-colors">
                    {student.full_name || 'Student'}
                  </span>
                  <span className="text-[9.5px] font-semibold text-zinc-400 mt-0.5 truncate">
                    {student.year ? `${student.year} Yr` : ''} {student.branch ? `┬╖ ${student.branch}` : ''}
                  </span>
                  <BookCoffeeButton 
                    targetUserId={student.id}
                    targetName={student.full_name}
                    targetPhoto={student.photo || student.instagram_photo || getCartoonAvatar(student.id)}
                    isLoggedIn={!!currentUserId}
                    accentColor="#7c3aed"
                    renderButton={({ onClick }) => (
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          onClick(e);
                        }}
                        className="mt-2 w-full py-1.5 rounded-xl bg-purple-600 hover:bg-purple-700 transition-colors text-white text-[10px] font-black flex items-center justify-center gap-1 shadow-sm cursor-pointer"
                      >
                        Meet 50 <Zap className="w-3 h-3 text-yellow-300 fill-current" />
                      </button>
                    )}
                  />
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';
import React, { useState, useEffect, useRef } from 'react';
import Image from 'next/image';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import {
  Home, Search, Users, User, LogIn, Wallet, Shield, Plus, Bell, Zap, MessageSquare,
  LayoutDashboard, CreditCard, ArrowUpRight, ShieldCheck, FileText, Settings, MoreHorizontal, Calendar, BookOpen
} from 'lucide-react';
import { getUserAvatarUrl } from '../utils/avatar';
import { db } from '../lib/firebaseClient';
import { collection, query, where, onSnapshot } from 'firebase/firestore';

const AUTH_PATHS = ['/login', '/signup', '/onboarding'];

function MeetifyLogo({ size = 32, animate = false }) {
  return (
    <div
      className={animate ? 'logo-ring-animation' : ''}
      style={{
        width: size,
        height: size,
        borderRadius: Math.round(size * 0.3),
        background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        flexShrink: 0,
        boxShadow: animate
          ? '0 0 0 4px rgba(124,58,237,0.25), 0 2px 8px rgba(124,58,237,0.3)'
          : '0 2px 8px rgba(124,58,237,0.3)',
        transition: 'box-shadow 0.3s ease',
      }}
    >
      <svg width={size * 0.6} height={size * 0.6} viewBox="0 0 24 24" fill="none">
        <path d="M3 18V9l9 6 9-6v9" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M3 9l9-6 9 6" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    </div>
  );
}

export default function Sidebar({ user }) {
  const pathname = usePathname();
  const router = useRouter();
  const isAdminRoute = pathname.startsWith('/admin');

  const [sparks, setSparks] = useState(
    user?.wallet ? (user.wallet.purchased || 0) + (user.wallet.bonus || 0) + (user.wallet.creator || 0) : 0
  );

  // ΓöÇΓöÇ Notification state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const [unreadCount, setUnreadCount] = useState(0);
  const [unreadMsgCount, setUnreadMsgCount] = useState(0); // Unread messages badge
  const [logoAnimating, setLogoAnimating] = useState(false);
  const prevCountRef = useRef(0);
  const prevMsgCountRef = useRef(0);
  const isOnNotifPage = pathname === '/notifications';

  // Notification loader
  useEffect(() => {
    if (!user?.id) return;

    let unsub = null;
    let pollInterval = null;

    const fetchApiCount = async () => {
      try {
        const res = await fetch('/api/notifications');
        if (!res.ok) return;
        const data = await res.json();
        const count = data.unreadCount || 0;
        setUnreadCount(count);
        if (count > prevCountRef.current && prevCountRef.current !== 0) {
          setLogoAnimating(true);
          setTimeout(() => setLogoAnimating(false), 2000);
        }
        prevCountRef.current = count;
      } catch { /* silent */ }
    };

    fetchApiCount();

    if (db) {
      try {
        const notifRef = collection(db, 'users', user.id, 'notifications');
        const q = query(notifRef, where('read', '==', false));

        unsub = onSnapshot(q, (snap) => {
          const count = snap.size;
          setUnreadCount(count);
          if (count > prevCountRef.current && prevCountRef.current !== 0) {
            setLogoAnimating(true);
            setTimeout(() => setLogoAnimating(false), 2000);
          }
          prevCountRef.current = count;
        }, () => {
          if (!pollInterval) {
            pollInterval = setInterval(fetchApiCount, 15000);
          }
        });
      } catch {
        pollInterval = setInterval(fetchApiCount, 15000);
      }
    } else {
      pollInterval = setInterval(fetchApiCount, 15000);
    }

    return () => {
      if (unsub) unsub();
      if (pollInterval) clearInterval(pollInterval);
    };
  }, [user?.id]);

  useEffect(() => {
    if (isOnNotifPage && unreadCount > 0 && user?.id) {
      fetch('/api/notifications', { method: 'PATCH' })
        .then(() => setUnreadCount(0))
        .catch(() => {});
    }
  }, [isOnNotifPage]);

  // ΓöÇΓöÇ Unread Messages listener ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (!user?.id || !db) return;
    const isOnMessagesPage = pathname === '/messages';

    // Request Notification permission for PWA if not already granted/denied
    if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'default') {
      Notification.requestPermission();
    }

    try {
      const q = query(
        collection(db, 'chats'),
        where('participants', 'array-contains', user.id)
      );

      const unsub = onSnapshot(q, (snap) => {
        let totalUnread = 0;

        snap.forEach(d => {
          const data = d.data();
          const count = data.unreadCount?.[user.id] || 0;
          totalUnread += count;
        });

        setUnreadMsgCount(isOnMessagesPage ? 0 : totalUnread);

        // Trigger PWA notification if count goes up (new message received)
        if (totalUnread > prevMsgCountRef.current && prevMsgCountRef.current !== 0 && !isOnMessagesPage) {
          if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'granted') {
            new Notification('New Message on Meetify', {
              body: 'You received a new message from a campus student.',
              icon: '/icon-192.png',
              badge: '/icon-192.png',
            });
          }
        }

        prevMsgCountRef.current = totalUnread;
      }, () => {});

      return () => unsub();
    } catch { /* graceful fail */ }
  }, [user?.id, pathname]);

  // ΓöÇΓöÇ Wallet sync ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  useEffect(() => {
    const sync = async () => {
      try {
        const res = await fetch('/api/wallet');
        if (!res.ok) return;
        const data = await res.json();
        const w = data.wallet;
        if (w) setSparks((w.purchased || 0) + (w.bonus || 0) + (w.creator || 0));
      } catch { /* silent */ }
    };

    if (user && typeof window !== 'undefined') {
      sync();
      window.addEventListener('wallet-updated', sync);
      return () => window.removeEventListener('wallet-updated', sync);
    }
  }, [user]);

  const isActive = (href) => {
    if (href === '/') return pathname === '/';
    if (href === '/admin') return pathname === '/admin';
    return pathname.startsWith(href);
  };

  const NAV = [
    { href: '/',              label: 'Home',          Icon: Home },
    { href: '/discover',      label: 'Discover',      Icon: Search },
    { href: '/messages',      label: 'Messages',      Icon: MessageSquare },
    { href: '/bookings',      label: 'My Bookings',   Icon: Calendar },
    { href: '/notifications', label: 'Notifications', Icon: Bell },
    { href: '/circles',       label: 'Communities',   Icon: Users },
    ...(user ? [{ href: '/wallet', label: 'Wallet', Icon: Wallet }] : []),
    { href: '/profile',       label: 'Profile',       Icon: User },
    ...(user?.role === 'admin' ? [{ href: '/admin', label: 'Admin', Icon: Shield }] : []),
  ];

  const MOBILE_NAV = [
    { href: '/',         label: 'Home',     Icon: Home },
    { href: '/discover', label: 'Discover', Icon: Search },
    { href: '/create',   label: 'Plus',     Icon: Plus, isCenter: true },
    { href: '/bookings', label: 'Bookings', Icon: Calendar },
    { href: '/profile',  label: 'Profile',  Icon: User },
  ];

  const avatarSrc = getUserAvatarUrl(user);

  if (AUTH_PATHS.includes(pathname)) return null;

  return (
    <>
      <style>{`
        @keyframes logo-ring {
          0%   { transform: rotate(0deg) scale(1); }
          15%  { transform: rotate(-12deg) scale(1.1); }
          30%  { transform: rotate(10deg) scale(1.1); }
          45%  { transform: rotate(-8deg) scale(1.05); }
          60%  { transform: rotate(6deg) scale(1.05); }
          75%  { transform: rotate(-4deg) scale(1.02); }
          100% { transform: rotate(0deg) scale(1); }
        }
        .logo-ring-animation {
          animation: logo-ring 0.7s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
          animation-iteration-count: 2;
        }
      `}</style>

      {/* ΓöÇΓöÇ Mobile top header ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <header className="md:hidden fixed top-0 inset-x-0 z-50 h-[58px] flex items-center justify-between px-4 bg-white/90 backdrop-blur-xl border-b border-zinc-100 shadow-2xs">

        <Link href="/" className="flex items-center gap-2 group">
          <MeetifyLogo size={28} animate={logoAnimating} />
          <span className="font-black text-lg tracking-tight text-zinc-900">
            meetifyy
          </span>
        </Link>

        <div className="flex items-center gap-2.5">
          {user ? (
            <>
              {!isAdminRoute && (
                <Link 
                  href="/wallet" 
                  className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-black bg-purple-50 text-purple-700 border border-purple-100/80 hover:bg-purple-100/70 transition-all active:scale-95"
                >
                  <Zap size={13} className="fill-purple-600 text-purple-600" />
                  <span>{sparks.toLocaleString()}</span>
                </Link>
              )}

              {/* Notifications */}
              <Link 
                href="/notifications" 
                className={`relative p-2 rounded-full transition-all ${
                  pathname === '/notifications' 
                    ? 'text-purple-600 bg-purple-50' 
                    : 'text-zinc-700 hover:text-zinc-900 hover:bg-zinc-100/80'
                }`}
                title="Notifications"
              >
                <Bell size={20} className={unreadCount > 0 ? 'text-purple-600 fill-purple-100' : ''} strokeWidth={2.2} />
                {unreadCount > 0 && (
                  <span className="absolute top-1 right-1 w-2.5 h-2.5 rounded-full bg-purple-600 ring-2 ring-white" />
                )}
              </Link>

              {/* Messages */}
              <Link 
                href="/messages" 
                className={`relative p-2 rounded-full transition-all ${
                  pathname === '/messages' 
                    ? 'text-purple-600 bg-purple-50' 
                    : 'text-zinc-700 hover:text-zinc-900 hover:bg-zinc-100/80'
                }`}
                title="Messages"
              >
                <MessageSquare size={20} className={unreadMsgCount > 0 ? 'text-purple-600 fill-purple-100' : ''} strokeWidth={2.2} />
                {unreadMsgCount > 0 && (
                  <span className="absolute top-1 right-1 w-2.5 h-2.5 rounded-full bg-purple-600 ring-2 ring-white" />
                )}
              </Link>
            </>
          ) : (
            <Link 
              href="/login"
              className="px-4 py-1.5 rounded-full text-xs font-black text-white bg-purple-600 hover:bg-purple-700 active:scale-95 transition-all shadow-2xs"
            >
              Log in
            </Link>
          )}
        </div>
      </header>

      {/* ΓöÇΓöÇ Desktop sidebar ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <aside className="hidden md:flex flex-col fixed left-0 top-0 h-screen z-40"
        style={{ width: 220, background: '#ffffff', borderRight: '1px solid #f0f0f0', padding: '28px 16px' }}>

        <Link href="/" className="flex items-center gap-2.5 px-2 mb-10">
          <MeetifyLogo size={32} animate={logoAnimating} />
          <span className="font-black text-[18px] tracking-tight bg-gradient-to-r from-purple-700 via-indigo-600 to-pink-600 bg-clip-text text-transparent">meetifyy</span>
        </Link>

        <nav className="flex-1 space-y-0.5">
          {NAV.map(({ href, label, Icon }) => {
            if (href === '/profile' && !user) return null;
            const active = isActive(href);
            const isNotif = label === 'Notifications';
            const hasUnread = isNotif && unreadCount > 0;
            const isMessages = label === 'Messages';
            const hasUnreadMsgs = isMessages && unreadMsgCount > 0;

            return (
              <Link key={href} href={href}
                className="flex items-center justify-between px-3.5 py-2.5 rounded-xl text-[13px] font-medium transition-all"
                style={{ background: active ? '#f3f0ff' : 'transparent', color: active ? '#7c3aed' : '#71717a' }}>
                <div className="flex items-center gap-3 relative">
                  <Icon size={18} strokeWidth={active ? 2.5 : 1.75} />
                  <span style={{ fontWeight: active ? 800 : 500 }}>{label}</span>
                </div>
                {hasUnread && (
                  <span className="min-w-[20px] h-[20px] rounded-full bg-gradient-to-tr from-purple-600 to-pink-500 text-white text-[10px] font-black flex items-center justify-center px-1 shadow-2xs">
                    {unreadCount > 99 ? '99+' : unreadCount}
                  </span>
                )}
                {hasUnreadMsgs && (
                  <span className="min-w-[20px] h-[20px] rounded-full bg-gradient-to-tr from-purple-600 to-pink-500 text-white text-[10px] font-black flex items-center justify-center px-1 shadow-2xs">
                    {unreadMsgCount > 99 ? '99+' : unreadMsgCount}
                  </span>
                )}
                {label === 'Wallet' && sparks > 0 && (
                  <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-purple-100 text-purple-700">
                    {sparks.toLocaleString()}
                  </span>
                )}
              </Link>
            );
          })}
        </nav>

        <div style={{ borderTop: '1px solid #f0f0f0', paddingTop: 16, marginTop: 16 }}>
          {user ? (
            <Link href="/profile" className="flex items-center gap-2.5 p-2.5 rounded-xl transition-all hover:bg-purple-50/50 group">
              <div className="w-9 h-9 rounded-full p-[1.5px] bg-gradient-to-tr from-purple-600 to-indigo-500 flex-shrink-0">
                <div className="w-full h-full rounded-full overflow-hidden relative border border-white">
                  <Image src={avatarSrc} alt="me" fill sizes="36px" style={{ objectFit: 'cover' }} />
                </div>
              </div>
              <div className="min-w-0">
                <p className="text-xs font-black truncate text-zinc-900 group-hover:text-purple-600 transition-colors">{user.full_name || (user.email || 'user').split('@')[0]}</p>
                <p className="text-[10px] truncate text-zinc-400 font-semibold">
                  {isAdminRoute ? 'Super Admin' : `${user.year || '1st'} ┬╖ ${user.branch || 'General'}`}
                </p>
              </div>
            </Link>
          ) : (
            <Link href="/login" className="w-full flex items-center justify-center gap-2 py-2.5 rounded-xl text-xs font-black text-white bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-700 hover:to-indigo-700 transition-all shadow-xs">
              <LogIn size={14} /> Log in
            </Link>
          )}
        </div>
      </aside>

      {/* ΓöÇΓöÇ Mobile bottom tab bar ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <nav 
        className="md:hidden fixed bottom-0 inset-x-0 z-50 flex items-center justify-around bg-white/90 backdrop-blur-2xl border-t border-zinc-200/80 shadow-[0_-4px_24px_rgba(0,0,0,0.06)]"
        style={{
          height: 'calc(62px + env(safe-area-inset-bottom))',
          paddingBottom: 'env(safe-area-inset-bottom)',
        }}
      >
        {MOBILE_NAV.map(({ href, label, Icon, isCenter }) => {
          if ((href === '/profile') && !user) {
            return (
              <Link key={href} href="/login" className="flex-1 flex flex-col items-center justify-center h-full text-zinc-400 hover:text-purple-600 transition-colors">
                <LogIn size={20} strokeWidth={2} />
                <span className="text-[10px] font-black mt-0.5">Login</span>
              </Link>
            );
          }
          const active = isActive(href);

          if (isCenter) {
            return (
              <Link 
                key={href} 
                href={href}
                className="flex-1 flex flex-col items-center justify-center relative -top-3 h-full select-none"
                style={{ zIndex: 60 }}
              >
                <div className="w-13 h-13 rounded-full flex items-center justify-center bg-gradient-to-tr from-purple-600 via-indigo-600 to-pink-500 text-white shadow-[0_8px_20px_rgba(124,58,237,0.4)] active:scale-90 transition-all ring-4 ring-white">
                  <Plus size={24} strokeWidth={2.8} />
                </div>
              </Link>
            );
          }

          return (
            <Link 
              key={href} 
              href={href}
              className={`flex-1 flex flex-col items-center justify-center h-full relative select-none transition-all ${
                active ? 'text-purple-600' : 'text-zinc-400 hover:text-zinc-600'
              }`}
            >
              <div className={`p-1.5 rounded-full transition-all ${active ? 'bg-purple-50/90 text-purple-600' : ''}`}>
                <Icon size={20} strokeWidth={active ? 2.6 : 1.9} />
              </div>
              <span className={`text-[10px] font-black -mt-0.5 tracking-tight ${active ? 'text-purple-600' : 'text-zinc-400'}`}>
                {label}
              </span>
              {active && (
                <span className="absolute top-0.5 left-1/2 -translate-x-1/2 w-5 h-0.5 rounded-full bg-gradient-to-r from-purple-600 to-indigo-600" />
              )}
            </Link>
          );
        })}
      </nav>
    </>
  );
}

// Client Component: responsive top navigation bar for Black and White Theme
'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Menu, X } from 'lucide-react';
import { useState } from 'react';

const NAV_ITEMS = [
  { href: '/', label: 'HOME' },
  { href: '/events', label: 'EVENTS' },
  { href: '/circles', label: 'CIRCLES' },
  { href: '/profile', label: 'PROFILE' },
];

export default function TopNav({ user }) {
  const pathname = usePathname();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  return (
    <nav className="bg-black border-b border-[#222222] sticky top-0 z-50">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">

          {/* Logo */}
          <div className="flex-shrink-0 flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg overflow-hidden flex items-center justify-center">
              <img src="/logo.png" alt="meetifyy logo" className="w-full h-full object-cover" />
            </div>
            <Link href="/" className="font-extrabold text-xl text-white tracking-tight">
              meetifyy
            </Link>
          </div>

          {/* Desktop Nav */}
          <div className="hidden md:flex flex-1 justify-center gap-8">
            {NAV_ITEMS.map(({ href, label }) => {
              if (href === '/profile' && !user) return null;

              const isActive = href === '/' ? pathname === '/' : pathname.startsWith(href);
              return (
                <Link
                  key={href}
                  href={href}
                  className={`text-xs font-bold tracking-[0.2em] uppercase transition-colors relative py-5 ${
                    isActive ? 'text-white' : 'text-[#888888] hover:text-white'
                  }`}
                >
                  {label}
                  {isActive && (
                    <span className="absolute bottom-0 left-0 w-full h-0.5 bg-white rounded-t-full" />
                  )}
                </Link>
              );
            })}
          </div>

          {/* Right Actions */}
          <div className="hidden md:flex items-center justify-end">
            {!user ? (
              <Link
                href="/login"
                className="text-xs font-extrabold text-black bg-white hover:bg-gray-200 px-5 py-2.5 rounded-full transition-colors uppercase tracking-widest"
              >
                LOG IN
              </Link>
            ) : (
              <Link href="/profile" className="flex items-center gap-2 group">
                <div className="w-8 h-8 rounded-full bg-[#111111] border border-[#333333] group-hover:border-white text-white font-bold flex items-center justify-center text-xs transition-colors">
                  {user.email?.[0].toUpperCase() || 'U'}
                </div>
              </Link>
            )}
          </div>

          {/* Mobile menu button */}
          <div className="flex items-center md:hidden">
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="text-[#888888] hover:text-white focus:outline-none"
            >
              {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden bg-black border-t border-[#222222] px-4 pt-4 pb-6 space-y-2 absolute w-full left-0 shadow-2xl">
          {NAV_ITEMS.map(({ href, label }) => {
            if (href === '/profile' && !user) return null;
            const isActive = href === '/' ? pathname === '/' : pathname.startsWith(href);
            return (
              <Link
                key={href}
                href={href}
                onClick={() => setIsMobileMenuOpen(false)}
                className={`block px-4 py-3 rounded-xl text-sm font-bold tracking-[0.2em] uppercase border ${
                  isActive ? 'bg-white text-black border-white' : 'text-[#888888] hover:bg-[#111111] hover:text-white border-transparent'
                }`}
              >
                {label}
              </Link>
            );
          })}
          {!user && (
            <Link
              href="/login"
              onClick={() => setIsMobileMenuOpen(false)}
              className="block px-4 py-3 mt-4 rounded-xl text-sm font-bold tracking-[0.2em] uppercase text-black bg-white text-center"
            >
              LOG IN
            </Link>
          )}
        </div>
      )}
    </nav>
  );
}

